<script setup lang="ts">
import {Button,Input,Checkbox,NativeSelect,Popover,Dialog} from '@openclaw-plugins/control-ui-kit';
import {useLogConsole,type LogOptions} from './useLogConsole';
import {capabilities,fullTime,moment} from './log-model';
import HighlightedText from './HighlightedText.vue';
import LogJsonTree from './LogJsonTree.vue';
const props=defineProps<LogOptions&{actionsContainer?:HTMLElement}>();
const {root,viewport,setFindInput,setMoreButton,rendered,safe,mode,source,level,category,groupBy,find,onlyMatches,mergeRepeats,selected,follow,historyLoading,findIndex,findOpen,clearing,confirmation,feedback,moreOpen,rawOpen,sources,filtered,matches,selectedEvent,categories,rawJson,stats,canClear,clearDisabled,canToggle,empty,lease,starting,connection,totalSize,expandedRepeats,collapsed,labelFor,refresh,foldAll,unfoldAll,toggleGroup,toggleRepeat,showEvent,showFind,closeFind,move,clearView,copy,download,toggle,setMode,confirmClear,clearStored,scrolled,keydown}=useLogConsole(props);
const levelLabels:Record<string,string>={debug:'调试',info:'信息',warn:'警告',error:'错误'};
function menu(action:()=>unknown){moreOpen.value=false;action();}
defineExpose({refresh});
</script>
<template><section ref="root" class="ar-console-shell" :data-view="mode" @keydown="keydown"><div class="ar-console-modebar"><nav class="ar-maintenance-views ar-console-tabs" aria-label="日志视图"><Button variant="ghost" :aria-current="mode==='history'?'page':'false'" @click="setMode('history')">历史记录</Button><Button variant="ghost" :aria-current="mode==='live'?'page':'false'" @click="setMode('live')">实时调试</Button></nav><span class="ar-console-status" :data-state="mode==='history'?'history':starting?'connecting':lease?'live':connection">{{mode==='history'?'已保存记录':starting?'连接中':lease?'采集中':connection==='error'?'已断开':'未开启'}}</span><Button class="ar-console-live" :hidden="mode!=='live'" :disabled="!canToggle" :aria-pressed="!!lease||starting" @click="toggle">{{starting?'取消连接':lease?'关闭实时调试':'开启实时调试'}}</Button><Teleport v-if="actionsContainer" :to="actionsContainer"><Button variant="outline" :disabled="mode==='history'&&historyLoading" @click="refresh">{{mode==='history'?'刷新日志':'刷新来源'}}</Button></Teleport><Button v-else variant="outline" :disabled="mode==='history'&&historyLoading" @click="refresh">{{mode==='history'?'刷新日志':'刷新来源'}}</Button></div>
<section class="ar-console"><div class="ar-console-toolbar"><NativeSelect v-model="source" aria-label="日志来源" title="筛选当前视图，不改变采集来源"><option value="">全部来源</option><option v-for="row in sources" :key="row.id" :value="row.id">{{safe(row.label+' · '+(capabilities(row).history&&capabilities(row).live?'历史 / 实时':capabilities(row).history?'历史':'仅实时'))}}</option></NativeSelect><NativeSelect v-model="level" aria-label="日志级别"><option value="">全部级别</option><option v-for="(label,value) in levelLabels" :key="value" :value="value">{{label}}</option></NativeSelect><Button variant="outline" :hidden="mode!=='live'" :aria-pressed="follow" @click="follow=!follow">跟随最新</Button>
<Popover v-model:open="moreOpen" @close-auto-focus="event=>{if(findOpen)event.preventDefault()}" label="日志更多操作"><template #trigger><Button :ref="setMoreButton" class="ar-console-more" variant="ghost" title="查找日志：⌘F / Ctrl+F">更多操作</Button></template><Button variant="ghost" :disabled="!filtered.length" @click="copy">复制筛选结果</Button><Button variant="ghost" :disabled="!filtered.length" @click="download">导出筛选结果</Button><Button variant="ghost" @click="menu(clearView)">清空当前视图</Button><Button variant="ghost" @click="showFind">查找日志</Button><label class="ocp:grid ocp:gap-1">分类<NativeSelect v-model="category" aria-label="日志分类"><option value="">全部分类</option><option v-for="value in categories" :key="value" :value="value">{{safe(value)}}</option></NativeSelect></label><label class="ocp:grid ocp:gap-1">分组<NativeSelect v-model="groupBy" aria-label="日志分组"><option value="">按时间排列</option><option value="sourceId">按来源分组</option><option value="jobId">按任务分组</option><option value="category">按分类分组</option></NativeSelect></label><label class="ocp:flex ocp:items-center ocp:gap-2" title="仅合并相邻且来源、任务、追踪及内容相同的记录，原始事件仍全部保留"><Checkbox :model-value="mergeRepeats" @update:model-value="mergeRepeats=$event===true" aria-label="合并连续重复记录"/>合并连续重复记录</label><Button variant="ghost" @click="menu(foldAll)">折叠全部</Button><Button variant="ghost" @click="menu(unfoldAll)">展开全部</Button><Button class="ar-console-danger" variant="ghost" :hidden="!canClear" :disabled="clearDisabled" @click="confirmClear">清理来源历史</Button><details class="ar-log-raw" @toggle="rawOpen=($event.target as HTMLDetailsElement).open"><summary>查看筛选结果 JSON</summary><textarea class="ocp:w-full ocp:min-h-40 ocp:border ocp:rounded-md ocp:bg-background ocp:p-2 ocp:font-mono ocp:text-xs" readonly aria-label="当前筛选结果 JSON" :value="rawJson"/></details></Popover></div>
<p class="ar-log-feedback" role="status" :hidden="!feedback">{{feedback}}</p>
<div class="ar-console-find" :hidden="!findOpen"><Input :ref="setFindInput" v-model="find" type="search" aria-label="查找日志" placeholder="查找内容、任务或追踪 ID"/><Button variant="ghost" :disabled="!matches.length" @click="move(-1)">上一个</Button><Button variant="ghost" :disabled="!matches.length" @click="move(1)">下一个</Button><span>{{find?findIndex<0?matches.length+' 个匹配':(findIndex+1)+' / '+matches.length:''}}</span><label><Checkbox :model-value="onlyMatches" @update:model-value="onlyMatches=$event===true" aria-label="仅显示匹配"/>仅显示匹配</label><Button variant="ghost" @click="closeFind">关闭查找</Button></div>
<div class="ar-console-workspace" :class="{'has-detail':!!selectedEvent}"><div class="ar-console-list"><section class="ar-log-empty" :hidden="!!filtered.length"><h3>{{empty.title}}</h3><p>{{empty.text}}</p><Button variant="outline" :hidden="!empty.live" @click="setMode('live')">查看实时调试</Button></section><div ref="viewport" tabindex="0" role="region" aria-label="日志控制台" class="ar-console-viewport" :hidden="!filtered.length" @scroll="scrolled"><div class="ar-console-canvas" :style="{height:totalSize+'px'}"><div v-for="{item,entry} in rendered" :key="entry.key" class="ar-console-line" :class="entry.type==='group'?'ar-console-group':entry.type==='date'?'ar-console-date':['ar-log-record',{'selected':selected===entry.event.eventId,'ar-console-repeat-child':entry.child}]" :data-key="entry.key" :data-level="entry.type==='event'?entry.event.level:undefined" :data-event-id="entry.type==='event'?entry.event.eventId:undefined" :style="{transform:'translateY('+item.start+'px)',height:item.size+'px'}"><Button v-if="entry.type==='group'" variant="ghost" :aria-expanded="!collapsed.has(entry.group)" @click="toggleGroup(entry.group)">{{(collapsed.has(entry.group)?'展开 ':'收起 ')+safe(entry.label)+' · '+entry.count}}</Button><template v-else-if="entry.type==='date'">{{entry.label}}</template><template v-else><time :title="fullTime(entry.event)">{{Number.isNaN(moment(entry.event).getTime())?'—':moment(entry.event).toLocaleTimeString([],{hour12:false})}}</time><span class="ar-console-level">{{levelLabels[entry.event.level]??entry.event.level}}</span><span class="ar-console-origin" :title="safe(entry.event.sourceId)">{{safe(labelFor(entry.event.sourceId))}}</span><Button class="ar-console-message ocp:h-auto" variant="ghost" data-control="message" :title="safe(entry.event.message)" @click="showEvent(entry.event)"><span class="ocp:block ocp:truncate"><HighlightedText :text="safe(entry.event.message)" :needle="find"/></span></Button><Button v-if="(entry.events?.length??0)>1" class="ar-console-repeat ocp:h-auto" variant="ghost" data-control="repeat" :aria-label="'重复 '+entry.events!.length+' 次'" :aria-expanded="expandedRepeats.has(entry.event.eventId)" :title="'首次 '+fullTime(entry.events![0]!)+'；末次 '+fullTime(entry.events!.at(-1)!)" @click="toggleRepeat(entry.event.eventId)">×{{entry.events!.length}}</Button></template></div></div></div></div>
<aside class="ar-console-inspector" aria-label="日志详情" :hidden="!selectedEvent"><div class="ar-console-detail-heading"><strong>{{selectedEvent?safe(labelFor(selectedEvent.sourceId)):'日志详情'}}</strong><Button variant="ghost" @click="selected=null;viewport?.focus()">关闭详情</Button></div><div class="ar-console-data"><LogJsonTree v-if="selectedEvent" :key="selectedEvent.eventId" :value="selectedEvent" label="事件" :needle="find" :safe="safe"/></div></aside></div><div class="ar-console-footer"><span>{{source?safe(labelFor(source)):mode==='history'?'支持历史读取的全部来源':'本次实时采集'}}</span><span class="ar-console-stats">{{stats}}</span></div></section></section><Dialog :open="!!confirmation" title="清理来源历史" :prevent-close="clearing" :show-close="false" @update:open="value=>{if(!value)confirmation=null}"><section v-if="confirmation" class="ar-log-confirm" role="group" aria-label="确认清理来源历史"><p>清理当前 Agent 的「{{safe(confirmation.label)}}」历史记录？仓库日志移入回收站，可在保留期内恢复；其他来源以其能力为准。当前筛选只影响显示，不缩小历史清理范围。</p><Button variant="outline" :disabled="clearing" @click="confirmation=null">取消</Button><Button variant="destructive" :disabled="clearing" @click="clearStored">确认清理</Button></section><p v-if="feedback" role="alert">{{feedback}}</p></Dialog></template>
